package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	Category string `json:"category"`
}

// sanitizeOrderBy attempts to prevent injection in ORDER BY clauses
// by removing dangerous characters
func sanitizeOrderBy(input string) string {
	// Remove semicolons and comments
	input = strings.ReplaceAll(input, ";", "")
	input = strings.ReplaceAll(input, "/*", "")
	input = strings.ReplaceAll(input, "*/", "")
	return input
}

// validateCategory checks category against known values
func validateCategory(cat string) bool {
	valid := []string{"electronics", "clothing", "food", "books", "toys"}
	for _, v := range valid {
		if strings.EqualFold(v, cat) {
			return true
		}
	}
	return false
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortCol := r.URL.Query().Get("sort")
	order := r.URL.Query().Get("order")

	if category == "" {
		category = "electronics"
	}

	if !validateCategory(category) {
		http.Error(w, "Invalid category", http.StatusBadRequest)
		return
	}

	// Default sort handling
	if sortCol == "" {
		sortCol = "name"
	}
	sortCol = sanitizeOrderBy(sortCol)

	if order == "" {
		order = "ASC"
	}
	// Normalize order direction
	order = strings.ToUpper(strings.TrimSpace(order))

	// Build query - category is validated, sort is sanitized
	query := fmt.Sprintf(
		"SELECT id, name, price, category FROM products WHERE category = $1 ORDER BY %s %s LIMIT 50",
		sortCol,
		order,
	)

	rows, err := db.Query(query, category)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Category); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
